18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
23	    @Mapping(target = "initials", expression = "java(initials(owner))")
24	    @Mapping(target = "locality", expression = "java(locality(owner))")
25	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
26	    @Mapping(target = "membershipTier", expression = "java(membershipTier(owner))")
27	    OwnerDto toOwnerDto(Owner owner);
28	
29	    /** The owner's name formatted as 'LastName, FirstName'. */
30	    default String displayName(Owner owner) {
31	        return owner == null ? null : owner.getLastName() + ", " + owner.getFirstName();
32	    }
33	
34	    /** The canonical region derived from the owner's city (see {@link CityRegion#of(String)}). */
35	    default String locality(Owner owner) {
36	        return owner == null ? null : CityRegion.of(owner.getCity());
37	    }
38	
39	    /** The upper-cased first letters of the first and last name, e.g. 'J.S.'. */
40	    default String initials(Owner owner) {
41	        return owner == null ? null
42	            : Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
43	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
44	    }
45	
46	    /**
47	     * The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is the
48	     * last two digits of the registration date's year, e.g. 'SYD-SMI-0007-M26'.
49	     */
50	    default String membershipNumber(Owner owner) {
51	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
52	            return null;
53	        }
54	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
55	    }
56	
57	    /**
58	     * The owner's membership tier: 'SILVER' when the owner has a unique name (namesakeCount is
59	     * zero) and an email address is present, otherwise 'BRONZE'.
60	     */
61	    default OwnerDto.MembershipTierEnum membershipTier(Owner owner) {
62	        if (owner == null) {
63	            return null;
64	        }
65	        Integer namesakeCount = owner.getNamesakeCount();
66	        boolean uniqueName = namesakeCount != null && namesakeCount == 0;
67	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
68	        return uniqueName && hasEmail ? OwnerDto.MembershipTierEnum.SILVER : OwnerDto.MembershipTierEnum.BRONZE;
69	    }
70	
71	    Owner toOwner(OwnerDto ownerDto);
72	
73	    @Mapping(target = "id", ignore = true)
74	    @Mapping(target = "pets", ignore = true)
75	    Owner toOwner(OwnerFieldsDto ownerDto);
76	
77	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
78	
79	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
80	
81	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
82	        OwnerPageDto ownerPageDto = new OwnerPageDto();
83	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
84	        ownerPageDto.setPage(ownerPage.getNumber());
85	        ownerPageDto.setSize(ownerPage.getSize());
86	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
87	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
88	        return ownerPageDto;
89	    }
