package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.util.BusinessDay;

/**
 * Resolves an owner's effective registration date and rolls it onto a business day. The effective
 * date is the one supplied on the create request, or the server's current date when the request
 * omits it. Either way, a Saturday or Sunday rolls forward to the following Monday (see
 * {@link BusinessDay#onOrAfter(LocalDate)}). Runs before the customer code, membership number and
 * daily create-limit are derived, so all of them key off the adjusted date. Mutates the built
 * {@link Owner} in place.
 */
public class ResolveRegistrationDate {

    public void service(@Val Owner owner) {
        LocalDate effective = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
        owner.setRegistrationDate(BusinessDay.onOrAfter(effective));
    }
}
===== EnsureDailyOwnerLimit.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.escalation.DailyOwnerLimitException;

/**
 * Rejects a create request once its business day's registrations have reached capacity: the day is
 * full when {@link #DAILY_LIMIT} or more existing owners already carry the new owner's (adjusted)
 * registration date. Runs after {@link ResolveRegistrationDate}, so a weekend request counts against
 * the Monday it rolled to. A full day is a 429 via {@link DailyOwnerLimitException}.
 */
public class EnsureDailyOwnerLimit {

    /** Maximum number of owners that may be registered on a single business day. */
    static final int DAILY_LIMIT = 100;

    public void service(@Val Owner owner, OwnerRepository ownerRepository) throws DailyOwnerLimitException {
        LocalDate day = owner.getRegistrationDate();
        long registeredThatDay = ownerRepository.countRegisteredOn(day);
        if (registeredThatDay >= DAILY_LIMIT) {
            throw new DailyOwnerLimitException(DAILY_LIMIT);
        }
    }
}
